import re

def solve(env, goal):
    def norm(s):
        return s.lower().rstrip('.').strip()

    def parse_goal(g):
        g = norm(g)
        m = re.search(r'(?:put|place|move)\s+(?:a\s+|an\s+)?(.+?)\s+(?:in|on|to)\s+(.+)$', g)
        if m:
            obj_phrase = re.sub(r'^(a|an|the)\s+', '', m.group(1).strip()).strip()
            rec_phrase = re.sub(r'^(a|an|the)\s+', '', m.group(2).strip()).strip()
            return obj_phrase, rec_phrase
        return None, None

    obj_type, rec_type = parse_goal(goal)
    if obj_type is None:
        return

    def base(phrase):
        return re.sub(r'\s+\d+$', '', phrase).strip().lower()

    def same_type(phrase, target):
        return base(phrase) == target.lower()

    def parse_items(obs):
        items = []
        for m in re.finditer(r'\b(a|an)\s+([a-z]+(?:\s[a-z]+)*)\s+(\d+)\b', obs):
            items.append((m.group(2).strip().lower(), m.group(3)))
        return items

    def parse_receptacles(obs):
        recs = []
        for m in re.finditer(r'\b([a-z]+(?:\s[a-z]+)*)\s+(\d+)\b', obs):
            name = m.group(1).strip().lower()
            num = m.group(2)
            if name in ('a', 'an', 'the'):
                continue
            recs.append((name, num))
        return recs

    def step(c):
        return env.step(c)

    def inventory_items():
        obs = step('inventory')
        return parse_items(obs)

    def find_held():
        for name, num in inventory_items():
            if same_type(name, obj_type):
                return ('%s %s' % (name, num), None)
        return (None, None)

    # initial room
    obs = step('look')
    recs = []
    seen = set()
    for name, num in parse_receptacles(obs):
        key = (name, num)
        if key not in seen:
            seen.add(key)
            recs.append(key)

    # check inventory
    held_full, _ = find_held()

    if held_full is None:
        # search receptacles
        found = None
        for name, num in recs:
            step('go to %s %s' % (name, num))
            r = step('look')
            if 'closed' in r.lower():
                step('open %s %s' % (name, num))
                r = step('look')
            items = parse_items(r)
            for it_name, it_num in items:
                if same_type(it_name, obj_type):
                    found = (name, num, '%s %s' % (it_name, it_num))
                    break
            if found:
                break
        if found is None:
            return
        loc_name, loc_num, obj_full = found
        step('go to %s %s' % (loc_name, loc_num))
        step('take %s from %s %s' % (obj_full, loc_name, loc_num))
        held_full = obj_full

    # find target receptacle
    obs = step('look')
    target = None
    for name, num in parse_receptacles(obs):
        if same_type(name, rec_type):
            target = (name, num)
            break
    if target is None:
        for name, num in recs:
            if same_type(name, rec_type):
                target = (name, num)
                break
    if target is None:
        return

    name, num = target
    step('go to %s %s' % (name, num))
    r = step('look')
    if 'closed' in r.lower():
        step('open %s %s' % (name, num))
    step('move %s to %s %s' % (held_full, name, num))
